let inletFit = [], outletFit = [], timeData = [];

// Extract data (robust)
context.panel.data.series.forEach((s) => {
  const timeField = s.fields.find(f => f.type === 'time');
  const valueField = s.fields.find(f => f.type === 'number');

  if (!timeField || !valueField) return;

  if (s.name === 'PSA_INLET_FIT') {
    timeData = timeField.values;
    inletFit = valueField.values;
  }

  if (s.name === 'PSA_OUTLET_FIT') {
    timeData = timeField.values;
    outletFit = valueField.values;
  }
});

// Format dates
const formattedDates = (timeData || []).map(d =>
  new Date(d).toLocaleDateString("en-IN", {
    timeZone: "Asia/Kolkata",
    month: "2-digit",
    day: "2-digit"
  })
);

// Align safely
const maxLen = Math.max(
  formattedDates.length,
  inletFit.length,
  outletFit.length
);

const safeDates = Array.from({ length: maxLen }, (_, i) => formattedDates[i] || '');

const safeInlet = Array.from({ length: maxLen }, (_, i) =>
  inletFit[i] == null || inletFit[i] <= 0 ? '-' : Math.round(inletFit[i])
);

const safeOutlet = Array.from({ length: maxLen }, (_, i) =>
  outletFit[i] == null || outletFit[i] <= 0 ? '-' : Math.round(outletFit[i])
);

// Data check
const hasData =
  inletFit.some(v => v != null) ||
  outletFit.some(v => v != null);

return {
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' }
  },
  legend: {
    data: ['PSA_INLET_FIT', 'PSA_OUTLET_FIT']
  },
  grid: {
    left: '5%',
    right: '4%',
    bottom: '10%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: safeDates.length ? safeDates : ['']
  },
  yAxis: {
    type: 'value',
    name: hasData ? 'Daily Flow Rate [M3/day]' : '',
    nameLocation: 'middle',
    nameGap: 70
  },
  series: [
    {
      name: 'PSA_INLET_FIT',
      type: 'bar',
      data: safeInlet
    },
    {
      name: 'PSA_OUTLET_FIT',
      type: 'bar',
      data: safeOutlet
    }
  ],
  graphic: !hasData ? {
    type: 'text',
    left: 'center',
    top: 'middle',
    style: {
      text: 'No data',
      fontSize: 18,
      fill: '#888'
    }
  } : undefined
};

